 "js/mod-game.css": "/* Scripting API UI. This stylesheet is loaded only in v3 engine sessions. */\n.sd-game-hud {\n  position: fixed;\n  right: max(16px, env(safe-area-inset-right));\n  top: max(110px, 18vh);\n  z-index: 64;\n  display: grid;\n  gap: 7px;\n  max-width: 200px;\n}\n.sd-game-hud[hidden], .sd-game-toast[hidden] { display: none; }\n.sd-game-pause, .sd-game-menu-items {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(132px, 1fr));\n  gap: 8px;\n}\n.sd-game-pause:not(:empty) { margin-block-start: 14px; }\n.sd-game-button {\n  background: #1b292f;\n  color: #e8f3f0;\n  border: 1px solid #52716c;\n  border-radius: 4px;\n  padding: .68em 1em;\n  font: 600 .9rem system-ui, sans-serif;\n  cursor: pointer;\n}\n.sd-game-button:is(:hover, :focus-visible) {\n  border-color: #a4e2ca;\n  background: #23504a;\n}\n.sd-game-menu {\n  width: min(470px, calc(100% - 28px));\n  max-height: min(680px, 85vh);\n  margin: auto;\n  color: #e8f3f0;\n  background: #122125;\n  border: 1px solid #638e81;\n  border-radius: 8px;\n  padding: clamp(16px, 5vw, 30px);\n  box-shadow: 0 20px 80px #000b;\n}\n.sd-game-menu::backdrop { background: #071015b8; }\n.sd-game-menu h2 { margin: 0 0 .55em; }\n.sd-game-menu p { margin: 0 0 1.2em; color: #afc8c1; }\n.sd-game-menu > button { margin-block-start: 12px; }\n.sd-game-toast, .sd-script-error {\n  position: fixed;\n  inset: auto 18px max(18px, env(safe-area-inset-bottom)) auto;\n  z-index: 80;\n  max-width: min(380px, 82vw);\n  border: 1px solid #659487;\n  background: #142629;\n  color: #e8f3f0;\n  padding: 12px 16px;\n  border-radius: 5px;\n  font: .9rem system-ui, sans-serif;\n  pointer-events: none;\n}\n.sd-script-error { inset: 16px 16px auto auto; border-color: #da9962; }\n.script-mod-session .mods-open, .script-mod-session .mod-play { display: none !important; }\n"
